# ============================================================================
#  Facet - Bazaar discovery overlay
#
#  Adds x402 Bazaar registration and a discovering agent. Run from the project
#  root, on top of an existing Facet install:
#
#      powershell -ExecutionPolicy Bypass -File .\install-bazaar.ps1
#
#  Bazaar is OFF by default. Nothing changes until you set BAZAAR_ENABLED=1,
#  so this is safe to apply to a working deployment.
#  Your .env is never touched.
# ============================================================================

$ErrorActionPreference = "Stop"

function Write-FacetFile {
    param([string]$Path, [string]$B64)
    $dir = Split-Path -Parent $Path
    if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $bytes = [System.Convert]::FromBase64String($B64)
    [System.IO.File]::WriteAllBytes((Join-Path $PWD.Path $Path), $bytes)
    "{0,-32} {1,7} bytes" -f $Path, $bytes.Length
}

Write-Host ""
Write-Host "Applying Bazaar overlay..." -ForegroundColor Cyan
Write-Host ""

